        for attr in ['data', 'timestamps', 'rate', 'unit', 'description']:
            if hasattr(obj, attr):
                val = getattr(obj, attr)
                try:
                    shp = val.shape
                except Exception:
                    shp = None
                if attr == 'description':
                    print('    ', attr, str(val)[:160])
                elif attr == 'timestamps':
                    if val is None:
                        print('    timestamps None')
                    else:
                        try:
                            print('    timestamps shape', val.shape)
                        except Exception:
                            print('    timestamps available')
                else:
                    print('    ', attr, shp if shp is not None else val)
    print('processing modules:')
    for mod_name, mod in nwb.processing.items():
        print(' module', mod_name)
        for name, obj in mod.data_interfaces.items():
            print('  ', name, type(obj).__name__)
            if hasattr(obj, 'time_series'):
                print('     time_series', list(obj.time_series.keys()))
            if hasattr(obj, 'spatial_series'):
                print('     spatial_series', list(obj.spatial_series.keys()))
            if hasattr(obj, 'roi_response_series'):
                print('     roi_response_series', list(obj.roi_response_series.keys()))
                for rs_name, rs in obj.roi_response_series.items():
                    print('       ', rs_name, 'data shape', rs.data.shape, 'rate', getattr(rs, 'rate', None), 'unit', getattr(rs, 'unit', None))
                    if rs.timestamps is not None:
                        try:
                            print('         timestamps shape', rs.timestamps.shape)
                        except Exception:
                            print('         timestamps available')
    print('intervals keys', list(nwb.intervals.keys()))
    print('invalid_times', nwb.invalid_times)
